function normalizeCompanyVouchers(comp) {
  if (!comp) return;
  const demo = getStandardDemoData();
  
  if (!comp.customers || comp.customers.length === 0) {
    comp.customers = [demo.demo_cust_1, demo.demo_cust_2];
  }
  if (!comp.quotations || comp.quotations.length === 0) {
    comp.quotations = [demo.demo_quotation];
  }
  if (!comp.proformas || comp.proformas.length === 0) {
    comp.proformas = [demo.demo_proforma];
  }
  if (!comp.challans || comp.challans.length === 0) {
    comp.challans = [demo.demo_challan];
  }
  if (!comp.invoices || comp.invoices.length === 0) {
    comp.invoices = [demo.demo_invoice];
  }
  
  comp.creditNotes = comp.creditNotes || [];
  comp.debitNotes = comp.debitNotes || [];
  comp.items = comp.items || [];
  comp.counterQuote = Math.max(comp.counterQuote || 101, 102);
  comp.counterProforma = Math.max(comp.counterProforma || 101, 102);
  comp.counterInvoice = Math.max(comp.counterInvoice || 101, 102);
  comp.counterChallan = Math.max(comp.counterChallan || 101, 102);
  comp.counterCreditNote = comp.counterCreditNote || 101;
  comp.counterDebitNote = comp.counterDebitNote || 101;
}


