                      <button onclick="downloadDocPDF('creditNote', '${cn.id}')" title="Download PDF" class="p-1 rounded text-slate-600 hover:text-rose-700 hover:bg-slate-100"><i data-lucide="download" class="w-3.5 h-3.5"></i></button>
